#import "HXScriptStore.h"
static const unsigned long long HXMaximumScriptBytes = 4ULL * 1024ULL * 1024ULL;
@implementation HXScriptStore
+ (instancetype)sharedStore { static HXScriptStore *s; static dispatch_once_t once; dispatch_once(&once, ^{ s=[HXScriptStore new]; }); return s; }
- (NSURL *)directory { NSURL *d=[[[NSFileManager defaultManager] URLsForDirectory:NSDocumentDirectory inDomains:NSUserDomainMask] firstObject]; return [d URLByAppendingPathComponent:@"LuaScripts" isDirectory:YES]; }
- (BOOL)ensure:(NSError **)error { return [[NSFileManager defaultManager] createDirectoryAtURL:self.directory withIntermediateDirectories:YES attributes:nil error:error]; }
- (NSString *)filename:(NSString *)name { NSString *n=[[name stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet] lastPathComponent]; n=[n stringByDeletingPathExtension]; NSCharacterSet *bad=[NSCharacterSet characterSetWithCharactersInString:@"<>:\"/\\|?*\n\r"]; n=[[n componentsSeparatedByCharactersInSet:bad] componentsJoinedByString:@"_"]; n=[n stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet]; if(!n.length)n=@"script"; if(n.length>80)n=[n substringToIndex:80]; return [n stringByAppendingPathExtension:@"lua"]; }
- (NSArray<NSDictionary *> *)allScripts:(NSError **)error { if(![self ensure:error])return @[]; NSArray *urls=[[NSFileManager defaultManager] contentsOfDirectoryAtURL:self.directory includingPropertiesForKeys:@[NSURLFileSizeKey,NSURLContentModificationDateKey] options:NSDirectoryEnumerationSkipsHiddenFiles error:error]; NSMutableArray *a=[NSMutableArray array]; for(NSURL *u in urls?:@[]){ if(![u.pathExtension.lowercaseString isEqualToString:@"lua"])continue; NSNumber *sz=nil; NSDate *dt=nil; [u getResourceValue:&sz forKey:NSURLFileSizeKey error:nil]; [u getResourceValue:&dt forKey:NSURLContentModificationDateKey error:nil]; [a addObject:@{@"name":u.lastPathComponent.stringByDeletingPathExtension,@"size":sz?:@0,@"modified":@((dt?:NSDate.date).timeIntervalSince1970)}]; } [a sortUsingComparator:^NSComparisonResult(NSDictionary *x,NSDictionary *y){return [y[@"modified"] compare:x[@"modified"]];}]; return a; }
- (BOOL)saveScriptNamed:(NSString *)name code:(NSString *)code error:(NSError **)error { NSData *data=[code dataUsingEncoding:NSUTF8StringEncoding]; if(data.length>HXMaximumScriptBytes){if(error)*error=[NSError errorWithDomain:@"HXScriptStore" code:2 userInfo:@{NSLocalizedDescriptionKey:@"脚本超过 4 MB 限制"}];return NO;} if(![self ensure:error])return NO; NSURL *url=[self.directory URLByAppendingPathComponent:[self filename:name?:@""]]; return [data writeToURL:url options:NSDataWritingAtomic error:error]; }
- (NSString *)loadScriptNamed:(NSString *)name error:(NSError **)error { NSURL *url=[self.directory URLByAppendingPathComponent:[self filename:name?:@""]]; NSDictionary *attrs=[[NSFileManager defaultManager] attributesOfItemAtPath:url.path error:error]; if(!attrs)return nil; if([attrs fileSize]>HXMaximumScriptBytes){if(error)*error=[NSError errorWithDomain:@"HXScriptStore" code:3 userInfo:@{NSLocalizedDescriptionKey:@"脚本超过 4 MB 限制"}];return nil;} return [NSString stringWithContentsOfURL:url encoding:NSUTF8StringEncoding error:error]; }
- (BOOL)deleteScriptNamed:(NSString *)name error:(NSError **)error { NSURL *url=[self.directory URLByAppendingPathComponent:[self filename:name?:@""]]; if(![[NSFileManager defaultManager] fileExistsAtPath:url.path])return YES; return [[NSFileManager defaultManager] removeItemAtURL:url error:error]; }
@end
